WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, DATE_TRUNC('DAY', reading_ts) AS activity_day, device_code, MIN(reading_ts) AS first_reading_ts, COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END) AS dv_02_count, COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END) AS dv_03_count, ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS pressure_per_dv_04, BIT_OR(status_bits) AS status_bits_bit_or, COUNT(*) FILTER (WHERE device_code = 'DV-03') AS dv_03_rows FROM sessions_device_readings GROUP BY CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('DAY', reading_ts), device_code ORDER BY device_code DESC NULLS LAST;
